    if (s == null || s.isEmpty()) {
        return false;
    }

    // Check if the input length is valid
    if (k < 1 || k > s.length()) {
        return false;
    }

    // Create a set to store all substrings of length k
    Set<String> substrings = new HashSet<>();

    // Iterate over the input string
    for (int i = 0; i < s.length() - k + 1; i++) {
        // Get the current substring
        String substring = s.substring(i, i + k);

        // Check if the substring is already in the set
        if (substrings.contains(substring)) {
            // If it is, return false
            return false;
        }

        // Add the substring to the set
        substrings.add(substring);
    }

    // If all substrings are unique, return true
