public int findMinFibonacciNumbers(int k) {
    // Edge case: k = 1
    if (k == 1) {
        return 1;
    }

    // Initialize variables
    int n = 2;
    int sum = 1;
    int count = 1;

    // Loop until the sum is equal to k
    while (sum < k) {
        // Calculate the next Fibonacci number
        int next = sum + n;
        n = sum;
        sum = next;
        count++;
    }

    // Check if the sum is equal to k
    if (sum == k) {
        return count;
    }

    // If the sum is not equal to k, return -1
    return -1;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        throw new IllegalArgumentException("n and k must be positive");
    }

    int[] factors = getFactors(n);
    if (factors.length < k) {
        return -1;
    }

    return factors[k - 1];
}

private int[] getFactors(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }

    int[] factors = new int[n];
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            factors[factors.length - 1] = i;
        }
    }

    return factors;
}

